nextflow_process {

    name "Test Process OATK"
    script "../main.nf"
    process "OATK"
    config "./nextflow.config"

    tag "oatk"
    tag "modules"
    tag "modules_nfcore"

    test("test_oatk_mito") {

        when {

            params {
                oatk_args = "-k 1001 -c 10"
            }

            process {
                """
                input[0] = [
                    [id:"ilDeiPorc1"],
                    file(params.modules_testdata_base_path + 'genomics/eukaryotes/deilephila_porcellus/mito/ilDeiPorc1.HiFi.reads.fa', checkIfExists: true)
                ]
                input[1] = [
                    [id: "mito"],
                    [
                        file("https://raw.githubusercontent.com/c-zhou/OatkDB/main/v20230921/insecta_mito.fam", checkIfExists: true),
                        file("https://github.com/c-zhou/OatkDB/raw/main/v20230921/insecta_mito.fam.h3f", checkIfExists: true),
                        file("https://github.com/c-zhou/OatkDB/raw/main/v20230921/insecta_mito.fam.h3i", checkIfExists: true),
                        file("https://github.com/c-zhou/OatkDB/raw/main/v20230921/insecta_mito.fam.h3m", checkIfExists: true),
                        file("https://github.com/c-zhou/OatkDB/raw/main/v20230921/insecta_mito.fam.h3p", checkIfExists: true)
                    ]
                ]
                input[2] = [[:], []]
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(
                    sanitizeOutput(
                        process.out,
                        unstableKeys: ["final_gfa", "initial_gfa", "annot_mito_txt", "oatk_log"],
                    )).match()
                }
            )
        }
    }

    test("test_oatk_pltd") {

        when {

            params {
                oatk_args = "-k 1001 -c 10"
            }

            process {
                """
                input[0] = [
                    [id:"ddAraThal4"],
                    file(params.modules_testdata_base_path + 'genomics/eukaryotes/arabidopsis_thaliana/plastid/ddAraThal4.HiFi.reads.fasta', checkIfExists: true)
                ]
                input[1] = [[:], []]
                input[2] = [
                    [id:"pltd"],
                    [
                        file("https://github.com/c-zhou/OatkDB/raw/main/v20230921/embryophyta_pltd.fam", checkIfExists: true),
                        file("https://github.com/c-zhou/OatkDB/raw/main/v20230921/embryophyta_pltd.fam.h3f", checkIfExists: true),
                        file("https://github.com/c-zhou/OatkDB/raw/main/v20230921/embryophyta_pltd.fam.h3i", checkIfExists: true),
                        file("https://github.com/c-zhou/OatkDB/raw/main/v20230921/embryophyta_pltd.fam.h3m", checkIfExists: true),
                        file("https://github.com/c-zhou/OatkDB/raw/main/v20230921/embryophyta_pltd.fam.h3p", checkIfExists: true)
                    ]
                ]
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(
                    sanitizeOutput(
                        process.out,
                        unstableKeys: ["final_gfa", "initial_gfa", "annot_pltd_txt", "oatk_log"],
                    )).match()
                }
            )
        }
    }

    test("test_oatk - mito and plastid") {

        when {

            params {
                oatk_args = "-k 1001 -c 10"
            }

            process {
                """
                input[0] = [
                    [id:"ddAraThal4"],
                    [
                        file(params.modules_testdata_base_path + 'genomics/eukaryotes/arabidopsis_thaliana/plastid/ddAraThal4.HiFi.reads.fasta', checkIfExists: true),
                        file(params.modules_testdata_base_path + 'genomics/eukaryotes/deilephila_porcellus/mito/ilDeiPorc1.HiFi.reads.fa', checkIfExists: true)
                    ]
                ]
                input[1] = [
                    [id: "mito"],
                    [
                        file("https://raw.githubusercontent.com/c-zhou/OatkDB/main/v20230921/insecta_mito.fam", checkIfExists: true),
                        file("https://github.com/c-zhou/OatkDB/raw/main/v20230921/insecta_mito.fam.h3f", checkIfExists: true),
                        file("https://github.com/c-zhou/OatkDB/raw/main/v20230921/insecta_mito.fam.h3i", checkIfExists: true),
                        file("https://github.com/c-zhou/OatkDB/raw/main/v20230921/insecta_mito.fam.h3m", checkIfExists: true),
                        file("https://github.com/c-zhou/OatkDB/raw/main/v20230921/insecta_mito.fam.h3p", checkIfExists: true)
                    ]
                ]
                input[2] = [
                    [id:"pltd"],
                    [
                        file("https://github.com/c-zhou/OatkDB/raw/main/v20230921/embryophyta_pltd.fam", checkIfExists: true),
                        file("https://github.com/c-zhou/OatkDB/raw/main/v20230921/embryophyta_pltd.fam.h3f", checkIfExists: true),
                        file("https://github.com/c-zhou/OatkDB/raw/main/v20230921/embryophyta_pltd.fam.h3i", checkIfExists: true),
                        file("https://github.com/c-zhou/OatkDB/raw/main/v20230921/embryophyta_pltd.fam.h3m", checkIfExists: true),
                        file("https://github.com/c-zhou/OatkDB/raw/main/v20230921/embryophyta_pltd.fam.h3p", checkIfExists: true)
                    ]
                ]
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(
                    sanitizeOutput(
                        process.out,
                        unstableKeys: ["final_gfa", "initial_gfa", "oatk_log", "annot_mito_txt", "annot_pltd_txt"],
                    )).match()
                }
            )
        }
    }

    test("test_oatk - stub") {

        options "-stub"

        when {

            params {
                oatk_args = "-k 1001 -c 10"
            }

            process {
                """
                input[0] = [
                    [id:"ddAraThal4"],
                    file(params.modules_testdata_base_path + 'genomics/eukaryotes/arabidopsis_thaliana/plastid/ddAraThal4.HiFi.reads.fasta', checkIfExists: true)
                ]
                input[1] = [[:], []]
                input[2] = [
                    [id:"pltd"],
                    [
                        file("https://github.com/c-zhou/OatkDB/raw/main/v20230921/embryophyta_pltd.fam", checkIfExists: true),
                        file("https://github.com/c-zhou/OatkDB/raw/main/v20230921/embryophyta_pltd.fam.h3f", checkIfExists: true),
                        file("https://github.com/c-zhou/OatkDB/raw/main/v20230921/embryophyta_pltd.fam.h3i", checkIfExists: true),
                        file("https://github.com/c-zhou/OatkDB/raw/main/v20230921/embryophyta_pltd.fam.h3m", checkIfExists: true),
                        file("https://github.com/c-zhou/OatkDB/raw/main/v20230921/embryophyta_pltd.fam.h3p", checkIfExists: true)
                    ]
                ]
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(sanitizeOutput(process.out)).match() }
            )
        }

    }
}
